// Statically compiled validation rules
use once_cell::sync::Lazy;
use regex::Regex;

static POSTAL_CODE_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"^[A-Z]\d[A-Z]\s?\d[A-Z]\d$").unwrap());

fn validate_postal_code(input: &str) -> bool {
    POSTAL_CODE_RE.is_match(input)
}

fn validate_input(value: &str) -> Result<(), &'static str> {
    if value.len() < 5 {
        return Err("Input must be at least 5 characters long");
    }
    if !value.chars().all(|c| c.is_alphanumeric()) {
        return Err("Input must be alphanumeric");
    }
    Ok(())
}
